// loop back-edges yield periodically so spin-waits (e.g. NCCL waitPeer)
// cannot starve the cooperative fiber scheduler
static inline void gx_ptx_spin_yield(void) {
    static thread_local unsigned _c = 0;
    if ((++_c & 63u) == 0) gx_cpu_kernel_yield();
}

