// PTX `mov` is a BIT move. Cross-register-class movs (mov.b32 %f, %r /
// mov.b64 %rd, %fd) must reinterpret bits — a C assignment would
// value-convert. gx_movb memcpys at the common width; gx_movpack/gx_movunpack
// are the brace-vector forms (mov.b64 %rd, {lo,hi} / mov.b64 {lo,hi}, %rd),
// joining/splitting at half the destination/source width (little-endian:
// first element is the low half, per PTX).
template <typename D, typename S>
static inline void gx_movb(D& d, S s) {
    if (sizeof(S) < sizeof(D)) d = D();
    memcpy(&d, &s, sizeof(D) < sizeof(S) ? sizeof(D) : sizeof(S));
}
template <typename D, typename A, typename B>
static inline void gx_movpack(D& d, A a, B b) {
    d = D();
    const size_t h = sizeof(D) / 2;
    unsigned char* p = (unsigned char*)&d;
    memcpy(p, &a, h < sizeof(A) ? h : sizeof(A));
    memcpy(p + h, &b, h < sizeof(B) ? h : sizeof(B));
}
template <typename A, typename B, typename S>
static inline void gx_movunpack(A& a, B& b, S s) {
    const size_t h = sizeof(S) / 2;
    const unsigned char* p = (const unsigned char*)&s;
    if (h < sizeof(A)) a = A();
    if (h < sizeof(B)) b = B();
    memcpy(&a, p, h < sizeof(A) ? h : sizeof(A));
    memcpy(&b, p + h, h < sizeof(B) ? h : sizeof(B));
}
// PTX vector mov: instruction-sized scalar, equally sized 2/4 fields,
// first field low. Width/count come from the opcode and braces, while C
// storage sizes validate the actual declarations rather than register names.
template <typename U, typename S>
static inline U gx_movread(S s) {
    static_assert(sizeof(U) == sizeof(S), "PTX vector mov scalar width");
    U bits = 0; memcpy(&bits, &s, sizeof(U)); return bits;
}
template <typename U, typename D, typename A, typename B>
static inline void gx_movpack2(D& d, A a, B b) {
    static_assert(sizeof(D) == sizeof(U) && sizeof(A) == sizeof(U)/2 &&
                  sizeof(B) == sizeof(U)/2, "PTX vector mov field widths");
    U bits = 0, lo = 0, hi = 0;
    memcpy(&lo, &a, sizeof(A)); memcpy(&hi, &b, sizeof(B));
    bits = lo | (hi << (sizeof(U)*4));
    memcpy(&d, &bits, sizeof(U));
}
template <typename U, typename D, typename A, typename B, typename C, typename E>
static inline void gx_movpack4(D& d, A a, B b, C c, E e) {
    static_assert(sizeof(D) == sizeof(U) && sizeof(A) == sizeof(U)/4 &&
                  sizeof(B) == sizeof(U)/4 && sizeof(C) == sizeof(U)/4 &&
                  sizeof(E) == sizeof(U)/4, "PTX vector mov field widths");
    U v0 = 0, v1 = 0, v2 = 0, v3 = 0;
    memcpy(&v0, &a, sizeof(A)); memcpy(&v1, &b, sizeof(B));
    memcpy(&v2, &c, sizeof(C)); memcpy(&v3, &e, sizeof(E));
    const unsigned width = sizeof(U)*2;
    U bits = v0 | (v1 << width) | (v2 << (2*width)) | (v3 << (3*width));
    memcpy(&d, &bits, sizeof(U));
}
template <typename U, unsigned Count, unsigned Index, typename D>
static inline void gx_movunpack_lane(D& d, U bits) {
    static_assert((Count == 2 || Count == 4) && Index < Count &&
                  sizeof(D) == sizeof(U)/Count, "PTX vector mov field width/index");
    U lane = bits >> (Index * (sizeof(U)*8/Count));
    memcpy(&d, &lane, sizeof(D));
}
