// PTX setp floating comparisons (ISA 9.3.1.2): even ordered `ne` is
// false for NaN. Compare IEEE encodings instead of host floating values so
// signaling NaNs and subnormals do not depend on the host FP environment.
// op: eq/ne/lt/le/gt/ge, then their unordered variants, then num/nan.
template <typename U>
static inline bool gx_setp_float_bits(U a, U b, unsigned op, bool ftz = false) {
    static_assert(sizeof(U) == 4 || sizeof(U) == 8, "setp needs binary32/64");
    const U sign = U(1) << (sizeof(U) * 8 - 1);
    const U infinity = sizeof(U) == 4 ? U(0x7f800000u) : U(0x7ff0000000000000ull);
    const U min_normal = sizeof(U) == 4 ? U(0x00800000u) : U(0x0010000000000000ull);
    U ma = a & ~sign, mb = b & ~sign;
    if (ftz) {
        if (ma < min_normal) { a &= sign; ma = 0; }
        if (mb < min_normal) { b &= sign; mb = 0; }
    }
    const bool unordered = ma > infinity || mb > infinity;
    if (op == 12) return !unordered;
    if (op == 13) return unordered;
    if (unordered) return op >= 6 && op < 12;
    const bool equal = a == b || (ma == 0 && mb == 0);
    const bool sa = (a & sign) != 0, sb = (b & sign) != 0;
    const bool less = !equal && (sa != sb ? sa : (sa ? ma > mb : ma < mb));
    switch (op % 6) {
    case 0: return equal;
    case 1: return !equal;
    case 2: return less;
    case 3: return less || equal;
    case 4: return !less && !equal;
    case 5: return !less;
    }
    return false;
}
// Two-source f32 min/max. PTX orders -0 below +0; .NaN propagates a
// canonical NaN, while the default returns the numeric operand. xorsign.abs
// uses original signs, even if one input was NaN and the other was selected.
static inline uint32_t gx_minmax_f32_bits(uint32_t a, uint32_t b,
                                        bool maximum, bool propagate_nan,
                                        bool xorsign_abs) {
    const uint32_t sign = (a ^ b) & 0x80000000u;
    if (xorsign_abs) { a &= 0x7fffffffu; b &= 0x7fffffffu; }
    const bool an = (a & 0x7fffffffu) > 0x7f800000u;
    const bool bn = (b & 0x7fffffffu) > 0x7f800000u;
    if ((an && bn) || (propagate_nan && (an || bn))) return 0x7fffffffu;
    uint32_t result;
    if (an) result = b;
    else if (bn) result = a;
    else if (((a | b) & 0x7fffffffu) == 0)
        result = maximum ? (a & b) : (a | b);
    else {
        const bool less = gx_setp_float_bits(a, b, 2);
        result = maximum ? (less ? b : a) : (less ? a : b);
    }
    return xorsign_abs ? ((result & 0x7fffffffu) | sign) : result;
}
