// Non-FTZ f32 forms preserve subnormal inputs. Host IEEE/libm and the
// default round-to-nearest mode remain trusted, as for other RN arithmetic.
// Exact f32 bit operations implement saturation and ties-to-even integer
// rounding without changing the host thread rounding state.
static inline float gx_cvt_sat_f32(float a) {
    uint32_t u; memcpy(&u, &a, 4);
    if ((u & 0x80000000u) || (u & 0x7fffffffu) > 0x7f800000u) u = 0;
    else if (u > 0x3f800000u) u = 0x3f800000u;
    memcpy(&a, &u, 4); return a;
}
static inline float gx_cvt_rni_f32(float a) {
    uint32_t u; memcpy(&u, &a, 4);
    const int e = int((u >> 23) & 255) - 127;
    if (e >= 23) return a;
    if (e < -1) u &= 0x80000000u;
    else if (e == -1) u = (u & 0x80000000u) | ((u & 0x007fffffu) ? 0x3f800000u : 0);
    else {
        const unsigned shift = 23 - e;
        const uint32_t mask = (1u << shift) - 1, rem = u & mask, half = 1u << (shift-1);
        u &= ~mask;
        if (rem > half || (rem == half && ((u >> shift) & 1u))) u += 1u << shift;
    }
    memcpy(&a, &u, 4); return a;
}
// PTX cvt.rzi/rmi.f32.f32 rounds to an integral value in f32 storage.
// Clear fractional significand bits, retaining signed zeros and subnormals'
// direction. No host float-to-int cast or ambient rounding mode is involved.
static inline float gx_cvt_rzi_f32(float a) {
    uint32_t u; memcpy(&u, &a, 4);
    const int e = int((u >> 23) & 255) - 127;
    if (e >= 23) return a; // Integral finite values, infinities, and NaNs.
    if (e < 0) u &= 0x80000000u;
    else u &= ~((1u << (23 - e)) - 1u);
    memcpy(&a, &u, 4); return a;
}
static inline float gx_cvt_rmi_f32(float a) {
    uint32_t u; memcpy(&u, &a, 4);
    const int e = int((u >> 23) & 255) - 127;
    if (e >= 23) return a;
    if (e < 0) {
        const bool negative_nonzero = (u >> 31) && (u & 0x7fffffffu);
        u = (u & 0x80000000u) | (negative_nonzero ? 0x3f800000u : 0u);
    } else {
        const uint32_t step = 1u << (23 - e), mask = step - 1u;
        const bool increment = (u >> 31) && (u & mask);
        u &= ~mask;
        if (increment) u += step;
    }
    memcpy(&a, &u, 4); return a;
}
// PTX cvt{.irnd}{.ftz}{.sat}.f32.f32: mode 0..3 = rni/rzi/rmi/rpi. Rounds to
// an integral value in f32 storage; .ftz flushes a subnormal input first and
// .sat then clamps to [+0, 1] with NaN -> +0. All steps are independent of the
// host rounding mode.
static inline float gx_cvt_irnd_f32(int mode, int ftz, int sat, float a) {
    if (ftz) a = gx_ftz_f32(a);
    switch (mode) {
    case 0: a = gx_cvt_rni_f32(a); break;
    case 1: a = gx_cvt_rzi_f32(a); break;
    case 2: a = gx_cvt_rmi_f32(a); break;
    default: a = ceilf(a); break;
    }
    return sat ? gx_cvt_sat_f32(a) : a;
}
