    if (mag >= 0x43e00000u) return (uint8_t)(sign | 0x7eu);
    unsigned e = mag >> 23;
    if (e < 117u) return (uint8_t)sign; // strictly below half min subnormal
    unsigned significand = (mag & 0x7fffffu) | 0x800000u;
    unsigned shift = e < 121u ? 141u - e : 20u;
    unsigned q = significand >> shift;
    unsigned rem = significand & ((1u << shift) - 1u);
    unsigned halfway = 1u << (shift - 1u);
    q += rem > halfway || (rem == halfway && (q & 1u));
    unsigned encoded = e < 121u ? q : (e - 121u) * 8u + q;
