// into a at pos; bits at/above the register width are unchanged).
// Proven model: Gxptx.CBits.bfi / bfi_spec (CSem.lean).
static inline uint32_t gx_bfi32(uint32_t ins, uint32_t base, uint32_t pos, uint32_t len) {
    pos &= 0xffu; len &= 0xffu;
    if (pos >= 32u) return base;
    uint32_t m = (len >= 32u) ? ~0u : ~(~0u << len);
    return (base & ~(m << pos)) | ((ins & m) << pos);
}
static inline uint64_t gx_bfi64(uint64_t ins, uint64_t base, uint32_t pos, uint32_t len) {
    pos &= 0xffu; len &= 0xffu;
    if (pos >= 64u) return base;
    uint64_t m = (len >= 64u) ? ~0ull : ~(~0ull << len);
    return (base & ~(m << pos)) | ((ins & m) << pos);
}
// Proven models: Gxptx.CBits.bfeU/bfeS and their per-bit specifications.
static inline uint32_t gx_bfe_u32(uint32_t a, uint32_t pos, uint32_t len) {
    pos &= 0xffu; len &= 0xffu;
    if (len == 0) return 0;
    if (pos >= 32) return 0;
    if (len >= 32) return a >> pos;
    return (a >> pos) & ~(~0u << len);
}
static inline int32_t gx_bfe_s32(uint32_t a, uint32_t pos, uint32_t len) {
    pos &= 0xffu; len &= 0xffu;
    if (len == 0) return 0;
    const uint32_t copied = pos < 32u ? ((len < 32u - pos) ? len : 32u - pos) : 0u;
    const uint32_t lowmask = copied == 32u ? ~0u : ((1u << copied) - 1u);
    const uint32_t extracted = pos < 32u ? (a >> pos) & lowmask : 0u;
    const uint32_t end = pos + len - 1u;
    const uint32_t signmask = ((a >> (end < 32u ? end : 31u)) & 1u) ? ~0u : 0u;
    return (int32_t)(extracted | (signmask & ~lowmask));
}
static inline uint64_t gx_bfe_u64(uint64_t a, uint32_t pos, uint32_t len) {
    pos &= 0xffu; len &= 0xffu;
    if (len == 0 || pos >= 64) return 0;
    if (len >= 64) return a >> pos;
    return (a >> pos) & ~(~0ull << len);
}
static inline int64_t gx_bfe_s64(uint64_t a, uint32_t pos, uint32_t len) {
    pos &= 0xffu; len &= 0xffu;
    if (len == 0) return 0;
    const uint32_t copied = pos < 64u ? ((len < 64u - pos) ? len : 64u - pos) : 0u;
    const uint64_t lowmask = copied == 64u ? ~0ull : (((uint64_t)1 << copied) - 1ull);
    const uint64_t extracted = pos < 64u ? (a >> pos) & lowmask : 0ull;
    const uint32_t end = pos + len - 1u;
    const uint64_t signmask = ((a >> (end < 64u ? end : 63u)) & 1ull) ? ~0ull : 0ull;
    return (int64_t)(extracted | (signmask & ~lowmask));
}

static inline uint64_t gx_clock64(void) {
    unsigned lo, hi;
    __asm__ __volatile__("rdtsc" : "=a"(lo), "=d"(hi));
    return ((uint64_t)hi << 32) | lo;
}
static inline uint32_t gx_brev32(uint32_t x) {
    x = ((x >> 1) & 0x55555555u) | ((x & 0x55555555u) << 1);
    x = ((x >> 2) & 0x33333333u) | ((x & 0x33333333u) << 2);
    x = ((x >> 4) & 0x0f0f0f0fu) | ((x & 0x0f0f0f0fu) << 4);
    return __builtin_bswap32(x);
}
static inline uint64_t gx_brev64(uint64_t x) {
    return ((uint64_t)gx_brev32((uint32_t)x) << 32) | gx_brev32((uint32_t)(x >> 32));
}
// bfind: position of most-significant set bit (~0 if none); .shiftamt
// returns the left-justify shift amount; signed variants scan ~a for a<0
static inline uint32_t gx_bfind32(uint32_t a, int shiftamt, int sgn) {
    if (sgn && (int32_t)a < 0) a = ~a;
    if (!a) return 0xffffffffu;
    uint32_t msb = 31 - __builtin_clz(a);
    return shiftamt ? 31 - msb : msb;
}
static inline uint32_t gx_bfind64(uint64_t a, int shiftamt, int sgn) {
    if (sgn && (int64_t)a < 0) a = ~a;
    if (!a) return 0xffffffffu;
    uint32_t msb = 63 - __builtin_clzll(a);
    return shiftamt ? 63 - msb : msb;
}

// Warp election. elect.sync chooses the least-numbered participating lane;
// all participating lanes receive its lane id and only that lane gets p=true.
static inline uint32_t gx_elect_lane(uint32_t mask) {
    return mask ? (uint32_t)__builtin_ctz(mask) : 0u;
}
static inline int gx_elect_pred(uint32_t mask) {
    __syncwarp_mask(mask);
    return mask && gx_lane_id() == gx_elect_lane(mask);
}
// ---- PTX shift / integer-divide semantics ---------------------------------
// C's <<, >>, / and % are undefined behavior exactly where PTX is defined:
//   * shift amounts >= register width (PTX clamps: shl/shr.u produce 0,
//     shr.s fills with the sign bit),
//   * integer division/remainder by zero and SR_MIN / -1 (PTX: machine-
//     specific garbage values, but NOT undefined).
// At -O1 LLVM (IPSCCP et al.) proves such expressions poison and deletes the
// surrounding paths, miscompiling translated kernels.  The emitter therefore
// calls these clamped/guarded helpers instead of the raw C operators.  The
// result type mirrors what the raw C operator would have produced (promoted
// type of the left operand for shifts, usual arithmetic conversions for
// division), so codegen is width-correct without the AST carrying widths.
template <typename T> struct gx_itr;  // integer traits: signed/unsigned twin
template <> struct gx_itr<int>                { typedef int R; typedef int S; typedef unsigned int U; };
template <> struct gx_itr<unsigned int>       { typedef unsigned int R; typedef int S; typedef unsigned int U; };
template <> struct gx_itr<long>               { typedef long R; typedef long S; typedef unsigned long U; };
template <> struct gx_itr<unsigned long>      { typedef unsigned long R; typedef long S; typedef unsigned long U; };
template <> struct gx_itr<long long>          { typedef long long R; typedef long long S; typedef unsigned long long U; };
template <> struct gx_itr<unsigned long long> { typedef unsigned long long R; typedef long long S; typedef unsigned long long U; };

template <typename T, typename V>
static inline auto gx_shl(T x, V y) -> decltype(x << 1) {
    typedef decltype(x << 1) R;
    const unsigned N = 8u * (unsigned)sizeof(R);
    return ((uint64_t)y >= N) ? (R)0 : (R)(x << (unsigned)y);
}
template <typename T, typename V>
static inline auto gx_shr(T x, V y) -> decltype(x >> 1) {  // logical
    typedef decltype(x >> 1) R;
    typedef typename gx_itr<R>::U UR;
    const unsigned N = 8u * (unsigned)sizeof(R);
    return ((uint64_t)y >= N) ? (R)0 : (R)((UR)(R)x >> (unsigned)y);
}
template <typename T, typename V>
static inline auto gx_sar(T x, V y) -> decltype(x >> 1) {  // arithmetic
    typedef decltype(x >> 1) R;
    typedef typename gx_itr<R>::S SR;
    const unsigned N = 8u * (unsigned)sizeof(R);
    unsigned k = ((uint64_t)y >= N) ? (N - 1u) : (unsigned)y;
    return (R)((SR)(R)x >> k);
}
template <typename T, typename V>
static inline auto gx_udiv(T a, V b) -> typename gx_itr<decltype(a / b)>::R {
    typedef decltype(a / b) R;
    typedef typename gx_itr<R>::U UR;
    UR ua = (UR)(R)a, ub = (UR)(R)b;
    return (R)(ub == 0 ? (UR)~(UR)0 : ua / ub);
}
template <typename T, typename V>
static inline auto gx_urem(T a, V b) -> typename gx_itr<decltype(a % b)>::R {
    typedef decltype(a % b) R;
    typedef typename gx_itr<R>::U UR;
    UR ua = (UR)(R)a, ub = (UR)(R)b;
    return (R)(ub == 0 ? ua : ua % ub);
}
template <typename T, typename V>
static inline auto gx_sdiv(T a, V b) -> typename gx_itr<decltype(a / b)>::R {
    typedef decltype(a / b) R;
    typedef typename gx_itr<R>::S SR;
    typedef typename gx_itr<R>::U UR;
    SR sa = (SR)(R)a, sb = (SR)(R)b;
    if (sb == 0)  return (R)(UR)~(UR)0;
    if (sb == -1) return (R)((UR)0 - (UR)sa);  // covers SR_MIN / -1 without UB
    return (R)(sa / sb);
}
template <typename T, typename V>
static inline auto gx_srem(T a, V b) -> typename gx_itr<decltype(a % b)>::R {
    typedef decltype(a % b) R;
    typedef typename gx_itr<R>::S SR;
    SR sa = (SR)(R)a, sb = (SR)(R)b;
    if (sb == 0)  return (R)sa;
    if (sb == -1) return (R)0;                 // covers SR_MIN % -1 without UB
    return (R)(sa % sb);
}
// div.f32/div.f64 are routed through the same emitter as unsigned integer
// div; IEEE float division (x/0 -> inf/nan) is fully defined, so it just
// passes through.  SFINAE (gx_ftr defined only for float/double, gx_itr only
// for integers) picks exactly one of the two gx_udiv templates per call.
template <typename T> struct gx_ftr;
template <> struct gx_ftr<float>  { typedef float  R; };
template <> struct gx_ftr<double> { typedef double R; };
template <typename T, typename V>
static inline auto gx_udiv(T a, V b) -> typename gx_ftr<decltype(a / b)>::R {
    return a / b;
}

extern "C" int gx_barrier_red_or(int bar, int count, int pred);
extern "C" int gx_barrier_red_and(int bar, int count, int pred);
extern "C" void gx_ptx_trap(void);
extern "C" void gx_ptx_trap_op(const char* op);

// Cluster geometry must come from the launch, never from a guessed unit
// cluster. Older launch backends deliberately fail when a kernel needs it.
extern "C" dim3 gx_dev_clusterDim(void) __attribute__((weak));
static inline dim3 gx_ptx_cluster_dim() {
    if (!gx_dev_clusterDim) {
        gx_ptx_trap_op("cluster geometry unavailable in launch backend");
        abort();
    }
    dim3 c = gx_dev_clusterDim(), g = gx_dev_gridDim();
    if (!c.x || !c.y || !c.z || g.x % c.x || g.y % c.y || g.z % c.z) {
        gx_ptx_trap_op("invalid cluster geometry");
        abort();
    }
    return c;
}
static inline dim3 gx_ptx_cluster_id() {
    dim3 c = gx_ptx_cluster_dim(), b = gx_dev_blockIdx();
    return {b.x / c.x, b.y / c.y, b.z / c.z};
}
static inline dim3 gx_ptx_cluster_grid() {
    dim3 c = gx_ptx_cluster_dim(), g = gx_dev_gridDim();
    return {g.x / c.x, g.y / c.y, g.z / c.z};
}
static inline uint32_t gx_ptx_cluster_ctarank() {
    dim3 c = gx_ptx_cluster_dim(), b = gx_dev_blockIdx();
    return (b.x % c.x) + c.x * ((b.y % c.y) + c.y * (b.z % c.z));
}
// ldmatrix.sync.aligned.m8n8.x1/x2/x4[.trans].shared.b16.
// NVIDIA PTX ISA: each lane supplies a 16-byte-aligned row address; lanes
// 0..7/8..15/16..23/24..31 supply matrices 0/1/2/3. Destination lane L
// receives row L/4, columns 2*(L%4),2*(L%4)+1 from each matrix.
// With .trans, it instead receives rows 2*(L%4),2*(L%4)+1 at column L/4.
// x1/x2 use only the first 8/16 supplier lanes, but all 32 lanes rendezvous.
// https://docs.nvidia.com/cuda/parallel-thread-execution/#warp-level-matrix-instructions-ldmatrix
// Existing full-warp shuffle rendezvous preserve 64-bit host shared pointers.
// No incomplete-warp or misalignment fallback. Divergent participation is an
// invalid PTX program and remains subject to the runtime's rendezvous checks.
struct gx_ldmatrix_x4 { uint32_t lane[4]; };
template<unsigned Matrices, bool Transpose>
static inline gx_ldmatrix_x4 gx_ldmatrix_m8n8_b16(uint64_t row_address) {
    static_assert(Matrices == 1 || Matrices == 2 || Matrices == 4, "ldmatrix count");
    const dim3 t = gx_dev_threadIdx(), b = gx_dev_blockDim();
    const uint64_t linear = ((uint64_t)t.z * b.y + t.y) * b.x + t.x;
    const uint64_t total = (uint64_t)b.x * b.y * b.z;
    gx_ldmatrix_x4 result{};
    if (linear >= total || ((linear / 32) + 1) * 32 > total) {
        gx_ptx_trap_op("ldmatrix.m8n8.x4.requires_full_warp");
        return result;
    }
    const unsigned lane = (unsigned)(linear % 32);
    for (unsigned matrix = 0; matrix < Matrices; ++matrix) {
      for (unsigned element = 0; element < (Transpose ? 2u : 1u); ++element) {
        const unsigned supplier = matrix * 8 + (Transpose ? 2 * (lane % 4) + element : lane / 4);
        const uint64_t lo = gx_shfl_sync((uint32_t)row_address, supplier, 31, ~0u, 0, nullptr);
        const uint64_t hi = gx_shfl_sync((uint32_t)(row_address >> 32), supplier, 31, ~0u, 0, nullptr);
        const uint64_t row = lo | (hi << 32);
        if ((row & 15u) != 0) {
            gx_ptx_trap_op("ldmatrix.m8n8.x4.row_alignment");
            return result;
        }
        if constexpr (Transpose) {
            uint16_t value;
            memcpy(&value, (const void*)(uintptr_t)(row + 2 * (lane / 4)), 2);
            result.lane[matrix] |= (uint32_t)value << (16 * element);
        } else {
            memcpy(&result.lane[matrix], (const void*)(uintptr_t)(row + 4 * (lane % 4)), 4);
        }
      }
    }
    // All fragment reads finish before a lane can overwrite shared source rows.
    __syncwarp_mask(~0u);
    return result;
}
// stmatrix inverts the corresponding ldmatrix fragment mapping. Warp-supplied
// row addresses may be non-contiguous; the transpose exchanges row/column.
template<unsigned Matrices, bool Transpose>
static inline void gx_stmatrix_m8n8_b16(uint64_t row_address,
        uint32_t v0, uint32_t v1, uint32_t v2, uint32_t v3) {
    static_assert(Matrices == 1 || Matrices == 2 || Matrices == 4, "stmatrix count");
    const dim3 t = gx_dev_threadIdx(), b = gx_dev_blockDim();
    const uint64_t linear = ((uint64_t)t.z * b.y + t.y) * b.x + t.x;
    const uint64_t total = (uint64_t)b.x * b.y * b.z;
    if (((linear / 32) + 1) * 32 > total) {
        gx_ptx_trap_op("stmatrix.requires_full_warp"); return;
    }
    const unsigned lane = linear % 32;
    const uint32_t values[4] = {v0, v1, v2, v3};
    __syncwarp_mask(~0u);
    for (unsigned matrix = 0; matrix < Matrices; ++matrix) {
        for (unsigned element = 0; element < (Transpose ? 2u : 1u); ++element) {
            const unsigned supplier = matrix * 8 +
                (Transpose ? 2 * (lane % 4) + element : lane / 4);
            const uint64_t lo = gx_shfl_sync((uint32_t)row_address, supplier, 31, ~0u, 0, nullptr);
            const uint64_t hi = gx_shfl_sync((uint32_t)(row_address >> 32), supplier, 31, ~0u, 0, nullptr);
            const uint64_t row = lo | (hi << 32);
            if (row & 15u) { gx_ptx_trap_op("stmatrix.row_alignment"); return; }
            if constexpr (Transpose) {
                uint16_t value = values[matrix] >> (16 * element);
                memcpy((void*)(uintptr_t)(row + 2 * (lane / 4)), &value, 2);
            } else {
                memcpy((void*)(uintptr_t)(row + 4 * (lane % 4)), &values[matrix], 4);
            }
        }
    }
    __syncwarp_mask(~0u);
}
// WGMMA (PTX ISA "Asynchronous Warpgroup Level Matrix Multiply-Accumulate
// Instructions") runs in the runtime (emu/ptx/wgmma.cc): every operation is an
// aligned 128-lane warpgroup rendezvous that completes eagerly. Format codes:
// 0 f16, 1 bf16, 2 e4m3, 3 e5m2, 4 tf32, 5 s8, 6 u8; dtype 0 f16, 1 f32,
// 2 s32; flags: 1 scale-d, 2 negate A, 4 negate B, 8 transpose A, 16
// transpose B, 32 A in registers, 64 satfinite. Collective kinds: 1 fence,
// 2 commit_group, 3 wait_group (count = N), 4/5 setmaxnreg.inc/.dec (count =
// imm-reg-count; a no-op register hint that still rendezvous the warpgroup).
extern "C" void gx_wgmma_mma_async(uint32_t n, uint32_t atype, uint32_t btype, uint32_t dtype,
                                   uint32_t flags, uint64_t desc_a, uint64_t desc_b,
                                   const uint32_t* a, uint32_t* d);
extern "C" void gx_wgmma_collective(uint32_t kind, uint32_t count);
// per-launch cooperative grid-sync workspace (envreg1/2 point here); the
// inlined cg grid_group::sync() protocol runs its atomics on word +4.
extern "C" uint64_t gx_grid_barrier_ptr(void);
extern "C" void gx_nccl_abort_poll(uint64_t address);
extern "C" void gx_ptx_vprintf(void** returns, void** inputs);
extern "C" void gx_ptx_assertfail(void** returns, void** inputs);

// Device payload may be fake either at GX's encoded high addresses or at
// ordinary virtual addresses registered by CUDA VMM. All direct memory helpers
// must consult the same allocation registry; address ranges alone are unsafe.
extern "C" int memory_mg_is_fake(void* address);
static inline int gx_fake(uint64_t a) {
    return memory_mg_is_fake((void*)(uintptr_t)a);
}
void global_memcpy(void* dst, const void* src, size_t size, int pos);
template <typename T> static inline T gx_gld(uint64_t a) {
    T value{};
    global_memcpy(&value, (const void*)(uintptr_t)a, sizeof(T), 1);
    return value;
}
// GX_GST_WATCH diagnostic: /tmp/gx_gst_watch holds "hexbase hexlen"; every
// global store touching [base, base+len) prints. The file is polled lazily
// so the watch range can be written mid-run. Off (one static check) unless
// the env is set.
extern "C" int open(const char*, int, ...);
extern "C" long read(int, void*, unsigned long);
extern "C" int close(int);
struct GxGstWatch { uint64_t base, len; unsigned long poll; int on; };
static inline void gx_gst_watch_check(uint64_t a, unsigned sz, uint64_t vbits) {
    static GxGstWatch w = {0, 0, 0, -1};
    if (w.on < 0) w.on = getenv("GX_GST_WATCH") ? 1 : 0;
    if (!w.on) return;
    if (!w.base && ((++w.poll & 0xffful) == 1)) {
        int fd = open("/tmp/gx_gst_watch", 0 /*O_RDONLY*/);
        if (fd >= 0) {
            char buf[64] = {0};
            long n = read(fd, buf, sizeof(buf) - 1);
            close(fd);
            if (n > 0) {
                uint64_t vals[2] = {0, 0};
                int vi = 0;
                for (long i = 0; i < n && vi < 2; i++) {
                    char c = buf[i];
                    int d = (c >= '0' && c <= '9') ? c - '0'
                          : (c >= 'a' && c <= 'f') ? c - 'a' + 10 : -1;
                    if (d >= 0) vals[vi] = vals[vi] * 16 + (uint64_t)d;
                    else if (vals[vi]) vi++;
                }
                w.base = vals[0];
                w.len = vals[1] ? vals[1] : 4096;
            }
        }
    }
    if (w.base && a + sz > w.base && a < w.base + w.len)
        printf("[gxgst] a=%llx sz=%u v=%llx\n", (unsigned long long)a, sz,
               (unsigned long long)vbits);
}
template <typename T> static inline void gx_gst(uint64_t a, T v) {
    uint64_t vb = 0;
    memcpy(&vb, &v, sizeof(T) < 8 ? sizeof(T) : 8);
    gx_gst_watch_check(a, (unsigned)sizeof(T), vb);
    global_memcpy((void*)(uintptr_t)a, &v, sizeof(T), 0);
}

// Preserve one PTX vector memory instruction as one GX memory operation.
template <typename T, unsigned N> struct GxGlobalVec { T lane[N]; };
template <typename T, unsigned N>
static inline GxGlobalVec<T, N> gx_gld_vec(uint64_t a) {
    GxGlobalVec<T, N> value{};
    global_memcpy(&value, (const void*)(uintptr_t)a, sizeof(value), 1);
    return value;
}
template <typename T, unsigned N>
static inline void gx_gst_vec(uint64_t a, GxGlobalVec<T, N> value) {
    global_memcpy((void*)(uintptr_t)a, &value, sizeof(value), 0);
}

// NCCL LL FIFO lines are {data1, flag1, data2, flag2}. Keep PTX's
// ld/st.volatile.global.v4.u32 as one 16-byte host access: four scalar loads
// can otherwise observe old data1 followed by new flags when an eight-slot
// FIFO line is reused, falsely accepting stale payload as the new line.
typedef uint32_t gx_u32x4 __attribute__((vector_size(16), aligned(1)));
static inline gx_u32x4 gx_gld_v4_u32(uint64_t a) {
    if (gx_fake(a)) return gx_u32x4{0, 0, 0, 0};
    return *(const volatile gx_u32x4*)(uintptr_t)a;
}
// Explicit arrival-vector annotation. Preserve the original 128-bit volatile
// read; retries do not count as useful HBM payload. The caller counts the
// successful vector once and checkpoints once per whole polling round.
static inline void gx_ptx_control_load_16(uint64_t dst, uint64_t src) {
    if (!dst || !src || src % 16 || gx_fake(src) || gx_fake(dst)) {
        gx_ptx_trap_op("gx_ptx_control_load_16.requires_real_aligned_memory");
        return;
    }
    gx_u32x4 value = *(const volatile gx_u32x4*)(uintptr_t)src;
    memcpy((void*)(uintptr_t)dst, &value, 16);
}
static inline void gx_gst_v4_u32(uint64_t a, uint32_t x0, uint32_t x1,
                                 uint32_t x2, uint32_t x3) {
    if (!gx_fake(a)) {
        gx_u32x4 v = {x0, x1, x2, x3};
        *(volatile gx_u32x4*)(uintptr_t)a = v;
    }
}

// ---- PTX atomics (atom/red) -------------------------------------------------
// Cross-PROCESS visibility is real under GX (peer PEs poke the same shm), so
// these must be genuine atomic RMWs. Fake device addresses (no backing) no-op
// like gx_gld/gx_gst; shared-window and shm addresses pass through.
static inline int gx_atom_dump_on(void) {
    static int dump = -1;
    if (dump < 0) dump = getenv("GX_ATOM_DUMP") ? 1 : 0;
    return dump;
}
template <typename T> static inline T gx_atom_add(uint64_t a, T v) {
    if (gx_fake(a)) {
        // fake-backed atomics silently no-op; when a workload spins on a
        // counter that never moves, this dump is the first thing to check
        if (gx_atom_dump_on())
            printf("[gxatom] FAKE add a=%llx v=%lld\n",
                   (unsigned long long)a, (long long)(int64_t)v);
        return (T)0;
    }
    T old = __atomic_fetch_add((T*)(uintptr_t)a, v, __ATOMIC_SEQ_CST);
    if (gx_atom_dump_on())
        printf("[gxatom] add a=%llx v=%lld old=%lld\n",
               (unsigned long long)a, (long long)(int64_t)v, (long long)(int64_t)old);
    return old;
}
template <typename T> static inline T gx_atom_max(uint64_t a, T v) {
    if (gx_fake(a)) return (T)0;
    T* p = (T*)(uintptr_t)a;
    T old = __atomic_load_n(p, __ATOMIC_SEQ_CST);
    while (old < v && !__atomic_compare_exchange_n(p, &old, v, 1, __ATOMIC_SEQ_CST,
                                                   __ATOMIC_SEQ_CST)) {}
    return old;
}
template <typename T> static inline T gx_atom_min(uint64_t a, T v) {
    if (gx_fake(a)) return (T)0;
    T* p = (T*)(uintptr_t)a;
    T old = __atomic_load_n(p, __ATOMIC_SEQ_CST);
    while (old > v && !__atomic_compare_exchange_n(p, &old, v, 1, __ATOMIC_SEQ_CST,
                                                   __ATOMIC_SEQ_CST)) {}
    return old;
}
template <typename T> static inline T gx_atom_exch(uint64_t a, T v) {
    if (gx_fake(a)) return (T)0;
    return __atomic_exchange_n((T*)(uintptr_t)a, v, __ATOMIC_SEQ_CST);
}
template <typename T> static inline T gx_atom_cas(uint64_t a, T cmp, T v) {
    if (gx_fake(a)) return (T)0;
    T expected = cmp;
    __atomic_compare_exchange_n((T*)(uintptr_t)a, &expected, v, 0, __ATOMIC_SEQ_CST,
                                __ATOMIC_SEQ_CST);
    return expected;
}
template <typename T> static inline T gx_atom_and(uint64_t a, T v) {
    if (gx_fake(a)) return (T)0;
    return __atomic_fetch_and((T*)(uintptr_t)a, v, __ATOMIC_SEQ_CST);
}
template <typename T> static inline T gx_atom_or(uint64_t a, T v) {
    if (gx_fake(a)) return (T)0;
    return __atomic_fetch_or((T*)(uintptr_t)a, v, __ATOMIC_SEQ_CST);
}
// Single round-to-nearest-even from double to binary16 / bfloat16 (sums of two
// 16-bit floats are exact in double, so these give correctly rounded adds).
static inline double gx_h2d(uint16_t h) { return double(gx_h2f(h)); }
static inline uint16_t gx_d2h_rn(double d) { _Float16 h = (_Float16)d; uint16_t u; memcpy(&u, &h, 2); return u; }
static inline uint16_t gx_d2bf_rn(double d) {
    if (d != d) return 0x7fc0u;
    const uint16_t sign = __builtin_signbit(d) ? 0x8000u : 0u;
    double a = __builtin_fabs(d);
    if (a == 0) return sign;
    int e; double m = __builtin_frexp(a, &e);           // a = m * 2^e, m in [0.5, 1)
    int exp = e - 1 + 127;
    double q;
    if (exp >= 1) q = __builtin_nearbyint(__builtin_ldexp(m, 8));          // 1.xxxxxxx scaled to [128,256)
    else { q = __builtin_nearbyint(__builtin_ldexp(a, 133)); exp = 0; }   // subnormal quantum 2^-133
    if (exp >= 1 && q == 256.0) { q = 128.0; ++exp; }
    if (exp == 0 && q >= 128.0) exp = 1;                                     // rounded up to the smallest normal
    if (exp >= 255) return uint16_t(sign | 0x7f80u);
    const uint16_t mant = exp ? uint16_t(uint32_t(q) - 128u) : uint16_t(q);
    return uint16_t(sign | (exp << 7) | mant);
}
// Generic atomic read-modify-write by compare-and-swap (PTX atom/red Table
// 35). op: 0 and, 1 or, 2 xor, 3 add, 4 inc, 5 dec, 6 min, 7 max, 8 add.f32,
// 9 add.f32 flushing subnormals (global memory), 10 add.f64, 11 add.f16,
// 12 add.f16x2, 13 add.bf16, 14 add.bf16x2, 15 exch. Float adds round to
// nearest even; 16-bit float adds preserve subnormals (.noftz).
template <typename T> static inline T gx_atom_apply(unsigned op, T r, T b) {
    auto f32 = [](uint32_t u) { float f; memcpy(&f, &u, 4); return f; };
    auto u32 = [](float f) { uint32_t u; memcpy(&u, &f, 4); return u; };
    auto flush = [](float f) { return __builtin_fpclassify(0, 1, 2, 3, 4, f) == 3 ? __builtin_copysignf(0.f, f) : f; };
    switch (op) {
    case 0: return r & b;
    case 1: return r | b;
    case 2: return r ^ b;
    case 3: return T(r + b);
    case 4: return r >= b ? T(0) : T(r + 1);
    case 5: return (r == 0 || r > b) ? b : T(r - 1);
    case 6: return r < b ? r : b;
    case 7: return r > b ? r : b;
    case 8: return T(u32(f32(uint32_t(r)) + f32(uint32_t(b))));
    case 9: return T(u32(flush(flush(f32(uint32_t(r))) + flush(f32(uint32_t(b))))));
    case 10: { double x, y; uint64_t ur = uint64_t(r), ub = uint64_t(b); memcpy(&x, &ur, 8); memcpy(&y, &ub, 8);
               x += y; uint64_t o; memcpy(&o, &x, 8); return T(o); }
    case 11: return T(gx_d2h_rn(gx_h2d(uint16_t(r)) + gx_h2d(uint16_t(b))));
    case 12: return T(uint32_t(gx_d2h_rn(gx_h2d(uint16_t(r)) + gx_h2d(uint16_t(b)))) |
                      (uint32_t(gx_d2h_rn(gx_h2d(uint16_t(uint32_t(r) >> 16)) + gx_h2d(uint16_t(uint32_t(b) >> 16)))) << 16));
    case 13: return T(gx_d2bf_rn(double(gx_bf2f(uint16_t(r))) + double(gx_bf2f(uint16_t(b)))));
    case 14: return T(uint32_t(gx_d2bf_rn(double(gx_bf2f(uint16_t(r))) + double(gx_bf2f(uint16_t(b))))) |
                      (uint32_t(gx_d2bf_rn(double(gx_bf2f(uint16_t(uint32_t(r) >> 16))) + double(gx_bf2f(uint16_t(uint32_t(b) >> 16))))) << 16));
    default: return b;   // 15 exch
    }
}
template <typename T> static inline T gx_atom_rmw(uint64_t a, unsigned op, T b) {
    if (gx_fake(a)) return (T)0;
    T* p = (T*)(uintptr_t)a;
    T old = __atomic_load_n(p, __ATOMIC_SEQ_CST);
    while (!__atomic_compare_exchange_n(p, &old, gx_atom_apply<T>(op, old, b), 1, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST)) {}
    return old;
}
// 128-bit exch/cas: GX fibers of one process run cooperatively, so a plain
// read-modify-write is atomic among them (cross-process 128-bit atomicity is
// not provided).
static inline unsigned __int128 gx_atom_b128(uint64_t a, bool cas, unsigned __int128 b, unsigned __int128 c) {
    if (gx_fake(a)) return 0;
    unsigned __int128 old; memcpy(&old, (const void*)(uintptr_t)a, 16);
    const unsigned __int128 nv = cas ? (old == b ? c : old) : b;
    memcpy((void*)(uintptr_t)a, &nv, 16);
    return old;
}
static inline uint32_t gx_atom_inc(uint64_t a, uint32_t v) {  // atom.inc wraps at v
    if (gx_fake(a)) return 0;
    uint32_t* p = (uint32_t*)(uintptr_t)a;
    uint32_t old = __atomic_load_n(p, __ATOMIC_SEQ_CST);
    for (;;) {
        uint32_t nv = (old >= v) ? 0 : old + 1;
        if (__atomic_compare_exchange_n(p, &old, nv, 1, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST))
            return old;
    }
}

// ---- mbarrier (shared::cta) -------------------------------------------------
// Hopper arrive/expect-tx barriers. All fibers of a block share one pthread
// (cooperative), and mbarriers live in the block's shared arena, so a plain
// side-table keyed by the barrier's host address is race-free per block; the
// mutex only guards the map across concurrent launches on other streams.
// Waits are driven by the PTX loop around try_wait (back-edges spin_yield).
#include <mutex>
#include <unordered_map>
struct GxMbarState { long long arrive_pending; long long tx_pending;
                     unsigned init_count; unsigned phase; };
inline std::unordered_map<uint64_t, GxMbarState>& gx_mbar_map() {
    static std::unordered_map<uint64_t, GxMbarState> m;
    return m;
}
inline std::mutex& gx_mbar_mu() { static std::mutex mu; return mu; }
static inline void gx_mbar_init(uint64_t a, unsigned count) {
    std::lock_guard<std::mutex> lk(gx_mbar_mu());
    gx_mbar_map()[a] = GxMbarState{(long long)count, 0, count, 0};
}
static inline void gx_mbar_inval(uint64_t a) {
    std::lock_guard<std::mutex> lk(gx_mbar_mu());
    gx_mbar_map().erase(a);
}
static inline void gx_mbar_complete(GxMbarState& s) {
    if (s.arrive_pending <= 0 && s.tx_pending <= 0) {
        s.phase ^= 1u;
        s.arrive_pending = (long long)s.init_count;
        s.tx_pending = 0;
    }
}
static inline void gx_mbar_arrive(uint64_t a, long long cnt) {
    std::lock_guard<std::mutex> lk(gx_mbar_mu());
    auto it = gx_mbar_map().find(a);
    if (it == gx_mbar_map().end()) return;
    it->second.arrive_pending -= cnt;
    gx_mbar_complete(it->second);
}
static inline void gx_mbar_arrive_expect_tx(uint64_t a, long long tx) {
    std::lock_guard<std::mutex> lk(gx_mbar_mu());
    auto it = gx_mbar_map().find(a);
    if (it == gx_mbar_map().end()) return;
    it->second.tx_pending += tx;
    it->second.arrive_pending -= 1;
    gx_mbar_complete(it->second);
}
static inline void gx_mbar_complete_tx(uint64_t a, long long bytes) {
    std::lock_guard<std::mutex> lk(gx_mbar_mu());
    auto it = gx_mbar_map().find(a);
    if (it == gx_mbar_map().end()) return;
    it->second.tx_pending -= bytes;
    gx_mbar_complete(it->second);
}
static inline int gx_mbar_try_wait_parity(uint64_t a, unsigned parity) {
    std::lock_guard<std::mutex> lk(gx_mbar_mu());
    auto it = gx_mbar_map().find(a);
    if (it == gx_mbar_map().end()) return 1;
    /* phase has moved past `parity` when it no longer equals it */
    return it->second.phase != parity;
}

// ---- TMA bulk copies (synchronous under GX) --------------------------------
// cp.async.bulk global<->shared: a plain memcpy NOW (the emulator has no
// async DMA), then complete_tx so the paired mbarrier accounting balances.
// commit_group/wait_group are no-ops (nothing is ever in flight).
static inline void gx_tma_g2s(uint64_t dst_shm, uint64_t src_global, uint32_t bytes,
                              uint64_t mbar) {
    if (!gx_fake(src_global))
        memcpy((void*)(uintptr_t)dst_shm, (const void*)(uintptr_t)src_global, bytes);
    else
        memset((void*)(uintptr_t)dst_shm, 0, bytes);
    gx_mbar_complete_tx(mbar, (long long)bytes);
}
static inline void gx_tma_s2g(uint64_t dst_global, uint64_t src_shm, uint32_t bytes) {
    if (!gx_fake(dst_global))
        memcpy((void*)(uintptr_t)dst_global, (const void*)(uintptr_t)src_shm, bytes);
}
static inline void gx_cpasync_g2s(uint64_t dst_shm, uint64_t src_global, uint32_t bytes) {
    if (!gx_fake(src_global))
        memcpy((void*)(uintptr_t)dst_shm, (const void*)(uintptr_t)src_global, bytes);
    else
        memset((void*)(uintptr_t)dst_shm, 0, bytes);
}

// ---- NVSHMEM device-side barrier substitution -------------------------------
// The real inlined NVSHMEM barriers walk team/psync state GX does not model,
// so their bodies are replaced. Both variants perform ONE PE-level arrival via
// the gx-nvshmem host lib (fiber-yield spin), resolved lazily so modules
// without nvshmem never need it.
typedef void (*gx_nvshmem_bar_fn)(void (*)(void));
static inline gx_nvshmem_bar_fn gx_nvshmem_resolve_barrier_fiber(void) {
    static gx_nvshmem_bar_fn fn;
    if (!fn) {
        void* h = dlsym(((void*)0), "gx_nvshmemx_barrier_all_fiber");
        if (!h) {
            /* drop-in loaded under an RTLD_LOCAL python extension:
             * fetch the loaded copy by soname (NOLOAD) */
            void* lib = dlopen("libgxnvshmem_host.so.3", RTLD_LAZY | RTLD_NOLOAD);
            if (!lib) lib = dlopen("libnvshmem_host.so.3", RTLD_LAZY | RTLD_NOLOAD);
            if (lib) h = dlsym(lib, "gx_nvshmemx_barrier_all_fiber");
        }
        fn = (gx_nvshmem_bar_fn)h;
    }
    return fn;
}
// nvshmemx_barrier_all_BLOCK: a BLOCK collective — every thread of the block
// calls it, so bracket the single PE arrival with __syncthreads and elect
// thread 0 to perform it.
static inline void gx_nvshmem_barrier_all_block_impl(void) {
    __syncthreads();
    dim3 t = gx_dev_threadIdx();
    if (t.x == 0 && t.y == 0 && t.z == 0) {
        gx_nvshmem_bar_fn fn = gx_nvshmem_resolve_barrier_fiber();
        if (!fn) { gx_ptx_trap_op("nvshmemx_barrier_all_block: gx-nvshmem host lib not loaded"); return; }
        fn(&gx_cpu_kernel_yield);
    }
    __syncthreads();
}
// nvshmem_sync_all / nvshmem_sync: a THREAD-callable PE collective (quiet +
// all-PE barrier). NVSHMEM (and DeepEP, which guards it with thread_id==0/32)
// call it from a SINGLE thread per PE — so NO __syncthreads (would deadlock:
// only one thread of the block is here) and NO thread-0 gate (the *calling*
// thread must perform the arrival, and it may be e.g. thread 32). Under GX
// p2p stores are synchronous, so the barrier alone provides quiet ordering.
static inline void gx_nvshmem_sync_impl(void) {
    gx_nvshmem_bar_fn fn = gx_nvshmem_resolve_barrier_fiber();
    if (!fn) { gx_ptx_trap_op("nvshmem_sync_all: gx-nvshmem host lib not loaded"); return; }
    fn(&gx_cpu_kernel_yield);
}

// Hopper bulk async copies are synchronous on the CPU emulator. This is
// stronger ordering than PTX; copy-group commit/wait can be no-ops. CTA
// mbarriers still track arrivals and transactions through the runtime hooks.
extern "C" int memory_mg_is_fake(void* address);
extern "C" void gx_cpu_kernel_poll(void);
// Annotation contract: this real, aligned word is immutable during the
// launch and each cohort lane reads it. Charge all original reads once;
// every lane still observes the actual word. No caching or polling semantics.
template<class T>
static inline T gx_ptx_uniform_load(uint64_t address, uint32_t lane, uint32_t lanes) {
    if (!lanes || lane >= lanes || !address || address % sizeof(T) ||
        memory_mg_is_fake((void*)(uintptr_t)address)) {
        gx_ptx_trap_op("gx_ptx_uniform_load.invalid_read");
        return {};
    }
    if (!lane) gx_nccl_payload_event_v2(address, uint64_t(lanes) * sizeof(T), 1, lanes);
    T value;
    __builtin_memcpy(&value, (const void*)(uintptr_t)address, sizeof(value));
    return value;
}
static inline uint64_t gx_ptx_uniform_load64(uint64_t address, uint32_t lane, uint32_t lanes) {
    return gx_ptx_uniform_load<uint64_t>(address, lane, lanes);
}
static inline uint32_t gx_ptx_counted_load32(uint64_t address, uint32_t count) {
    return gx_ptx_uniform_load<uint32_t>(address, 0, count);
}
extern "C" uint32_t gx_global_load_u8_repeated(uint64_t address, uint32_t count);
extern "C" uint32_t gx_global_load_u32_repeated(uint64_t address, uint32_t count);
extern "C" void gx_global_memcpy_counted(void*, const void*, size_t, int, uint64_t);
// A lane-private contiguous transfer with exactly one global endpoint. The
// source annotation supplies the original instruction width; no routing,
// synchronization or global byte/instruction accounting is omitted.
static inline void gx_ptx_counted_copy(uint64_t dst, uint64_t src, uint64_t bytes,
                                       uint32_t width, uint32_t is_load) {
    if (!width || width > 16 || (width & (width - 1)) ||
        bytes % width || bytes > SIZE_MAX || is_load > 1) {
        gx_ptx_trap_op("gx_ptx_counted_copy.invalid_shape");
        return;
    }
    if (!bytes) return;
    if (!dst || !src || (dst | src) % width) {
        gx_ptx_trap_op("gx_ptx_counted_copy.invalid_address");
        return;
    }
    gx_global_memcpy_counted((void*)(uintptr_t)dst, (const void*)(uintptr_t)src,
                             size_t(bytes), is_load, bytes / width);
}
// Strided FP32 gather through a shared, one-based index row. Outside the
// active range (or for nonpositive indices), store real zeros. The annotation
// requires immutable source values and a disjoint output row; its caller owns
// the producer/consumer barriers. Coalesce stores, not their modeled count.
static inline void gx_ptx_shared_index_gather_f32(uint64_t dst, uint64_t src,
        uint64_t indices, uint32_t begin, uint32_t end, uint32_t count,
        uint32_t lane, uint32_t stride) {
    if (!stride || lane >= stride || begin > end || end > count ||
        uint64_t(count) > SIZE_MAX / 4) {
        gx_ptx_trap_op("gx_ptx_shared_index_gather_f32.invalid_shape");
        return;
    }
    if (lane >= count) return;
    if (!dst || dst % 4 || memory_mg_is_fake((void*)(uintptr_t)dst) ||
        (begin != end && (!src || !indices || (src | indices) % 4 ||
         memory_mg_is_fake((void*)(uintptr_t)src) ||
         memory_mg_is_fake((void*)(uintptr_t)indices)))) {
        gx_ptx_trap_op("gx_ptx_shared_index_gather_f32.requires_real_memory");
        return;
    }
    const auto* index = (const int32_t*)(uintptr_t)indices;
    auto* output = (float*)(uintptr_t)dst;
    const auto* input = (const float*)(uintptr_t)src;
    for (uint64_t base = lane; base < count;) {
        // Only stride-one outputs form a contiguous write. Other lanes retain
        // their exact scalar stores and leave all intervening elements alone.
        const uint32_t n = stride == 1 ? uint32_t(count - base < 256 ? count - base : 256) : 1;
        float values[256] = {};
        for (uint32_t i = 0; i < n; ++i) {
            const uint64_t j = base + i;
            if (j < begin || j >= end) continue;
            const int32_t source = index[j - begin];
            if (source > 0)
                gx_global_memcpy_counted(values + i, input + uint64_t(source - 1), 4, 1, 1);
        }
        gx_global_memcpy_counted(output + base, values, size_t(n) * 4, 0, n);
        base += stride == 1 ? n : stride;
    }
}
// Masked matrix update: nonzero entries receive two immutable global column
// biases and one shared bias. No other block observes this tile until the
// caller's consumer barrier. Preserve conditional stores, overflow stores and
// repeated bias reads; coalesce only functional access to contiguous real data.
static inline void gx_ptx_masked_column_add_u32(uint64_t matrix, uint64_t bias1,
        uint64_t bias2, uint64_t shared_bias, uint64_t overflow,
        uint32_t count, uint32_t columns, uint64_t limit) {
    const dim3 block = gx_dev_blockDim(), lane = gx_dev_threadIdx();
    if (!block.x || block.x > 1024 || block.y != 1 || block.z != 1 ||
        lane.x >= block.x || lane.y || lane.z || !columns) {
        gx_ptx_trap_op("gx_ptx_masked_column_add_u32.invalid_shape");
        return;
    }
    if (lane.x || !count) return;
    const uint64_t addresses[] = {matrix, bias1, bias2, shared_bias, overflow};
    for (uint64_t address : addresses) {
        if (!address || address % 4 || memory_mg_is_fake((void*)(uintptr_t)address)) {
            gx_ptx_trap_op("gx_ptx_masked_column_add_u32.requires_real_memory");
            return;
        }
    }
    auto* output = (uint32_t*)(uintptr_t)matrix;
    const auto* shared = (const uint32_t*)(uintptr_t)shared_bias;
    for (uint32_t begin = 0; begin < count;) {
        const uint32_t n = count - begin < 256 ? count - begin : 256;
        uint32_t values[256], uses[256] = {}, biases[256];
        bool active[256];
        gx_global_memcpy_counted(values, output + begin, size_t(n) * 4, 1, n);
        for (uint32_t i = 0; i < n; ++i) {
            active[i] = values[i] != 0;
            uses[i % columns] += active[i];
        }
        for (uint32_t c = 0; c < columns && c < n; ++c) {
            if (!uses[c]) continue;
            const uint32_t column = (uint64_t(begin) + c) % columns;
            biases[c] = gx_global_load_u32_repeated(bias1 + uint64_t(column) * 4, uses[c]) +
                        gx_global_load_u32_repeated(bias2 + uint64_t(column) * 4, uses[c]) + shared[column];
        }
        for (uint32_t i = 0; i < n; ++i) if (active[i]) {
            values[i] += biases[i % columns];
            if (int64_t(int32_t(values[i])) > int64_t(limit)) {
                const uint32_t one = 1;
                gx_global_memcpy_counted((void*)(uintptr_t)overflow, &one, 4, 0, 1);
                values[i] = 0;
            }
        }
        for (uint32_t i = 0; i < n;) {
            if (!active[i]) { ++i; continue; }
            const uint32_t start = i++;
            while (i < n && active[i]) ++i;
            gx_global_memcpy_counted(output + begin + start, values + start,
                                     size_t(i - start) * 4, 0, i - start);
        }
        begin += n;
    }
}
// Explicit shared-matrix scan annotation: all block lanes arrive after the
// producer barrier and must reach the consumer barrier before using results.
// Only lane zero executes the matrix operation. This removes implementation
// rendezvous, never a communication wait. Every global total is still stored
// through the ordinary counted-memory path; shared accesses cost no HBM.
static inline void gx_ptx_masked_column_scan_u32(uint64_t tile_address,
                                                uint64_t totals_address,
                                                uint32_t columns) {
    const dim3 block = gx_dev_blockDim(), lane = gx_dev_threadIdx();
    if (!block.x || block.x > 1024 || block.y != 1 || block.z != 1 ||
        lane.x >= block.x || lane.y || lane.z ||
        columns > SIZE_MAX / (sizeof(uint32_t) * block.x)) {
        gx_ptx_trap_op("gx_ptx_masked_column_scan_u32.invalid_shape");
        return;
    }
    if (!columns || lane.x) return;
    if (!tile_address || !totals_address || (tile_address | totals_address) % 4 ||
        memory_mg_is_fake((void*)(uintptr_t)tile_address) ||
        memory_mg_is_fake((void*)(uintptr_t)totals_address)) {
        gx_ptx_trap_op("gx_ptx_masked_column_scan_u32.requires_real_memory");
        return;
    }
    auto* tile = (uint32_t*)(uintptr_t)tile_address;
    auto* totals = (uint32_t*)(uintptr_t)totals_address;
    for (uint32_t column = 0; column < columns; ++column) {
        uint32_t sum = 0;
        for (unsigned row = 0; row < block.x; ++row) {
            uint32_t& value = tile[size_t(row) * columns + column];
            const uint32_t input = value;
            sum += input;
            value = input == 1 ? sum : 0;
        }
        gx_global_memcpy_counted(totals + column, &sum, sizeof(sum), 0, 1);
    }
}
// Semantic annotation: every lane calls with the same contiguous tile and
// distinct lane IDs. The original surrounding barriers remain in the kernel.
// Only the global/shared data copy is coalesced; it is not a count-only event.
static inline void gx_ptx_block_copy16(uint64_t dst, uint64_t src, uint64_t count,
                                      uint32_t lane, uint32_t lanes, uint32_t is_load) {
    if (!lanes || lane >= lanes || is_load > 1 || count > SIZE_MAX / 16) {
        gx_ptx_trap_op("gx_ptx_block_copy16.invalid_shape");
        return;
    }
    if (!count || lane) return;
    if (!dst || !src || (dst | src) % 16) {
        gx_ptx_trap_op("gx_ptx_block_copy16.invalid_address");
        return;
    }
    gx_global_memcpy_counted((void*)(uintptr_t)dst, (const void*)(uintptr_t)src,
                             size_t(count) * 16, int(is_load), count);
}
// Contiguous cooperative tile transfer. The caller supplies the producer and
// consumer barriers. Preserve scalar instruction multiplicity, including real
// packed-boolean reads; only shared-memory conversion is performed locally.
static inline void gx_ptx_block_transfer_u32(uint64_t dst, uint64_t src,
                                            uint32_t count, uint32_t extent,
                                            uint32_t mode) {
    const dim3 block = gx_dev_blockDim(), lane = gx_dev_threadIdx();
    if (!block.x || block.x > 1024 || block.y != 1 || block.z != 1 ||
        lane.x >= block.x || lane.y || lane.z || mode > 2 || count > extent ||
        uint64_t(extent) > SIZE_MAX / 4) {
        gx_ptx_trap_op("gx_ptx_block_transfer_u32.invalid_shape");
        return;
    }
    if (lane.x || !extent || (mode == 1 && !count)) return;
    if (!dst || dst % 4 || memory_mg_is_fake((void*)(uintptr_t)dst) ||
        (count && (!src || (mode != 0 && src % 4) ||
                   memory_mg_is_fake((void*)(uintptr_t)src)))) {
        gx_ptx_trap_op("gx_ptx_block_transfer_u32.requires_real_memory");
        return;
    }
    auto* output = (uint32_t*)(uintptr_t)dst;
    if (mode == 0) {
        uint8_t values[256];
        for (uint32_t begin = 0; begin < count;) {
            const uint32_t n = count - begin < 256 ? count - begin : 256;
            gx_global_memcpy_counted(values, (const uint8_t*)(uintptr_t)src + begin,
                                     n, 1, n);
            for (uint32_t i = 0; i < n; ++i) output[begin + i] = values[i];
            begin += n;
        }
    } else if (count) {
        gx_global_memcpy_counted(output, (const void*)(uintptr_t)src,
                                 size_t(count) * 4, mode == 2, count);
    }
    if (mode != 1)
        for (uint32_t i = count; i < extent; ++i) output[i] = 0;
}

// Explicit control-poll annotation only. System/GPU scope maps to coherent
// host memory; acquire markers retain acquire ordering rather than weakening it.
// Do not turn this into a rule for all relaxed PTX loads: some carry payload.
template <typename T, int Order = __ATOMIC_RELAXED, bool Checkpoint = true>
static inline T gx_ptx_poll_load(uint64_t address) {
    static_assert(sizeof(T) == 4 || sizeof(T) == 8, "control poll width");
    if (!address || address % alignof(T) ||
        memory_mg_is_fake((void*)(uintptr_t)address)) {
        gx_ptx_trap_op("gx_ptx_poll_load.requires_real_aligned_memory");
        return {};
    }
    if constexpr (Checkpoint) gx_cpu_kernel_poll();
    return __atomic_load_n((const T*)(uintptr_t)address, Order);
}
static inline void gx_ptx_memcpy(uint64_t dst, uint64_t src, size_t bytes, int is_load) {
    // cp.async has exactly one global endpoint; the translator supplies its
    // direction. Use the same ownership, fake-memory and timing path as ld/st.
    // In particular fake payload still consumes bandwidth, while shared-memory
    // traffic is not accidentally charged as a second HBM access.
    if (bytes) global_memcpy((void*)(uintptr_t)dst,
                            (const void*)(uintptr_t)src, bytes, is_load);
}

// Binary64 -> binary32 rounding by encoding, independent of the host FP mode.
// mode: nearest-even, toward zero, toward -infinity, toward +infinity.
static inline float gx_cvt_f64_f32(unsigned mode, bool ftz, bool sat, double x) {
    uint64_t u; memcpy(&u, &x, 8);
    const uint32_t sign = uint32_t(u >> 32) & 0x80000000u;
    const unsigned exponent = unsigned((u >> 52) & 2047u);
    uint64_t mantissa = u & 0xfffffffffffffull;
    uint32_t bits;
    if (exponent == 2047) bits = sign | (mantissa ? 0x7fc00000u : 0x7f800000u);
    else if (!exponent && !mantissa) bits = sign;
    else {
        int e = exponent ? int(exponent) - 1023 : -1022;
        if (exponent) mantissa |= uint64_t(1) << 52;
        const unsigned shift = e >= -126 ? 29u : unsigned(-e - 97);
        uint64_t value = shift < 64 ? mantissa >> shift : 0;
        const uint64_t remainder = shift < 64 ? mantissa & ((uint64_t(1) << shift) - 1) : mantissa;
        bool increment = false;
        if (remainder) {
            if (mode == 0 && shift < 64) {
                const uint64_t half = uint64_t(1) << (shift - 1);
                increment = remainder > half || (remainder == half && (value & 1));
            } else if (mode == 2) increment = sign != 0;
            else if (mode == 3) increment = sign == 0;
        }
        value += increment;
        if (e >= -126) {
            if (value == (uint64_t(1) << 24)) { value >>= 1; ++e; }
            if (e > 127) {
                const bool inf = mode == 0 || (mode == 2 && sign) || (mode == 3 && !sign);
                bits = sign | (inf ? 0x7f800000u : 0x7f7fffffu);
            } else bits = sign | (uint32_t(e + 127) << 23) | (uint32_t(value) & 0x7fffffu);
        } else bits = sign | uint32_t(value);
    }
    if (ftz && (bits & 0x7fffffffu) < 0x00800000u) bits &= 0x80000000u;
    float result; memcpy(&result, &bits, 4);
    if (sat) {
        if (!(result > 0)) return 0.0f;
        if (result > 1) return 1.0f;
    }
    return result;
}

// WMMA uses a legal emulator-specific fragment mapping. A/B carry two copies
// of the 256 row-major logical half elements (16 per lane); C/D carry eight
// row-major elements per lane. No architecture-specific fragment indexing is
// promised by PTX. Only uniform register-wise fragment transforms are portable.
extern "C" void gx_wmma_m16n16k16_f16(const uint32_t*, const uint32_t*, const float*, float*);
extern "C" void gx_wmma_bf16(unsigned, unsigned, const uint32_t*, const uint32_t*, const float*, float*);
template<class T> static inline float gx_wmma_f32(T value) {
    static_assert(sizeof(T)==4, "WMMA accumulator register width");
    float f; memcpy(&f,&value,4); return f;
}
static inline void gx_wmma_sync() {
    const dim3 b=gx_dev_blockDim(); const unsigned n=b.x*b.y*b.z;
    if ((gx_warp_id()+1)*32>n) gx_ptx_trap_op("wmma.requires_full_warp");
    (void)gx_shfl_sync(0,0,31,0xffffffffu,0,nullptr);
}
static inline void gx_wmma_memory_check(uint64_t address, unsigned stride, unsigned bytes, unsigned minimum) {
    gx_wmma_sync();
    if ((address&15) || (uint64_t(stride)*bytes)%16 || stride<minimum)
        gx_ptx_trap_op("wmma.memory_alignment_or_stride");
    const uint32_t lo=gx_shfl_sync(uint32_t(address),0,31,0xffffffffu,0,nullptr);
    const uint32_t hi=gx_shfl_sync(uint32_t(address>>32),0,31,0xffffffffu,0,nullptr);
    const uint32_t ld=gx_shfl_sync(stride,0,31,0xffffffffu,0,nullptr);
    if (address!=(uint64_t(hi)<<32|lo) || stride!=ld)
        gx_ptx_trap_op("wmma.nonuniform_address_or_stride");
}
template<bool Guard,bool Column,unsigned Rows,unsigned Cols,unsigned Words,unsigned Space=0>
static inline void gx_wmma_load_16(uint64_t address,unsigned stride,uint32_t* out) {
    gx_wmma_memory_check(address,stride,2,Column?Rows:Cols);
    for(unsigned i=0;i<Words;++i) {
        uint32_t v=0;
        for(unsigned h=0;h<2;++h) {
            unsigned index=(gx_lane_id()*Words*2+i*2+h)%(Rows*Cols);
            unsigned row=index/Cols,col=index%Cols;
            uint64_t at=address+2*(uint64_t(Column?col:row)*stride+(Column?row:col));
            drperf_gpu_memory(at,2,0,Space);
            uint16_t x=Guard?gx_gld<uint16_t>(at):*(const uint16_t*)(uintptr_t)at;
            v|=uint32_t(x)<<(16*h);
        }
        out[i]=v;
    }
    gx_wmma_sync();
}
template<bool Guard,bool Column,unsigned Rows,unsigned Cols,unsigned Space=0>
static inline void gx_wmma_load_f32(uint64_t address,unsigned stride,float* out) {
    gx_wmma_memory_check(address,stride,4,Column?Rows:Cols);
    for(unsigned i=0;i<8;++i) {
        unsigned index=gx_lane_id()*8+i,row=index/Cols,col=index%Cols;
        uint64_t at=address+4*(uint64_t(Column?col:row)*stride+(Column?row:col));
        drperf_gpu_memory(at,4,0,Space);
        out[i]=Guard?gx_gld<float>(at):*(const float*)(uintptr_t)at;
    }
    gx_wmma_sync();
}
template<bool Guard,bool Column,unsigned Rows=16,unsigned Cols=16,unsigned Space=0>
static inline void gx_wmma_store_f32(uint64_t address,unsigned stride,const float* in) {
    gx_wmma_memory_check(address,stride,4,Column?Rows:Cols);
    for(unsigned i=0;i<8;++i) {
        unsigned index=gx_lane_id()*8+i,row=index/Cols,col=index%Cols;
        uint64_t at=address+4*(uint64_t(Column?col:row)*stride+(Column?row:col));
        drperf_gpu_memory(at,0,4,Space);
        if(Guard) gx_gst<float>(at,in[i]); else *(float*)(uintptr_t)at=in[i];
    }
    gx_wmma_sync();
}
extern "C" void gx_mma_sync_i8(unsigned, bool, bool, bool, const uint32_t*, const uint32_t*, const uint32_t*, uint32_t*);
extern "C" void gx_mma_sync(uint32_t, uint32_t, uint32_t, uint32_t, uint32_t, const uint32_t*, const uint32_t*,
                            const uint32_t*, uint32_t*);
